<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Nota {{ $order->order_code }}</title><style>*{box-sizing:border-box}body{margin:0;background:#e2e8f0;color:#0f172a;font:13px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace}.receipt{width:80mm;margin:24px auto;padding:18px;background:#fff}.center{text-align:center}.brand{font:bold 22px ui-sans-serif,system-ui}.muted{color:#64748b;font-size:11px}.rule{border:0;border-top:1px dashed #94a3b8;margin:14px 0}.row{display:flex;justify-content:space-between;gap:10px;margin:6px 0}.total{font-weight:bold;font-size:16px}.no-print{display:block;margin:0 auto 16px;padding:10px 18px;border:0;border-radius:8px;background:#10243e;color:#fff;font-weight:bold}@media print{body{background:#fff}.no-print{display:none!important}.receipt{width:80mm;margin:0;padding:0}@page{size:80mm auto;margin:5mm}}</style></head><body><button class="no-print" onclick="window.print()">Cetak Nota</button><main class="receipt"><div class="center"><div class="brand">Kang Laundry</div><div class="muted">Laundry bersih, hidup lebih ringan</div></div><hr class="rule"><div class="row"><span>ID Pesanan</span><strong>{{ $order->order_code }}</strong></div><div class="row"><span>Tanggal</span><span>{{ $order->created_at->format('d/m/Y H:i') }}</span></div><div class="row"><span>Pelanggan</span><span>{{ $order->customer_name }}</span></div><hr class="rule"><div class="row"><span>Berat</span><span>{{ $order->weight }} kg</span></div><div class="row"><span>Tarif</span><span>Rp {{ number_format(config('laundry.rate'), 0, ',', '.') }}/kg</span></div><div class="row total"><span>TOTAL</span><span>Rp {{ number_format($order->total_price, 0, ',', '.') }}</span></div><hr class="rule"><div class="center muted">Terima Kasih &amp; Silakan Simpan Nota Ini</div></main><script>window.addEventListener('load',()=>window.print())</script></body></html>
